function validate([edges]) {
  if (!Array.isArray(edges) || edges.length < 1 || edges.length > 100000) return 'edges needs 1 to 10^5 entries.';
  const n = edges.length;
  if (!Array.isArray(edges[0]) || edges[0].length !== 2 || edges[0][0] !== -1 || edges[0][1] !== -1) return 'edges[0] must be [-1, -1].';
  const children = Array.from({ length: n }, () => []);
  for (let i = 1; i < n; i++) {
    const edge = edges[i];
    if (!Array.isArray(edge) || edge.length !== 2) return 'Each entry is a [parent, weight] pair.';
    const [par, weight] = edge;
    if (!Number.isInteger(par) || par < 0 || par >= n || par === i) return 'Each parent is another node from 0 to n - 1.';
    if (!Number.isInteger(weight) || weight < -1000000 || weight > 1000000) return 'Each weight is an integer from -10^6 to 10^6.';
    children[par].push(i);
  }
  const order = [0];
  for (let i = 0; i < order.length; i++) for (const child of children[order[i]]) order.push(child);
  if (order.length !== n) return 'The parents must form one tree rooted at node 0.';
  return null;
}

