function maxScore(edges) {
  const n = edges.length;
  const children = Array.from({ length: n }, () => []);
  for (let node = 1; node < n; node++) {
    children[edges[node][0]].push(node);
  }
  const order = [0];
  for (let i = 0; i < order.length; i++) {
    for (const child of children[order[i]]) {
      order.push(child);
    }
  }
  const free = new Array(n).fill(0);
  const best = new Array(n).fill(0);
  for (let i = n - 1; i >= 0; i--) {
    const node = order[i];
    let sum = 0;
    for (const child of children[node]) {
      sum += best[child];
    }
    free[node] = sum;
    best[node] = sum;
    for (const child of children[node]) {
      const withEdge = sum - best[child] + free[child] + edges[child][1];
      best[node] = Math.max(best[node], withEdge);
    }
  }
  return best[0];
}

