  const n = edges.length;
  const m = n - 1;
  let answer = 0;
  for (let mask = 0; mask < (1 << m); mask++) {
    const used = new Set();
    let score = 0, ok = true;
    for (let e = 0; e < m && ok; e++) {
      if (!(mask & (1 << e))) continue;
      const a = e + 1, b = edges[e + 1][0];
      if (used.has(a) || used.has(b)) ok = false;
      used.add(a);
      used.add(b);
      score += edges[e + 1][1];
    }
    if (ok && score > answer) answer = score;
  }
  return answer;
}

