function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 10);
  const shape = Math.floor(rand() * 4);
  const limit = size === 'large' || rand() < 0.4 ? 1000000 : 10;
  const label = [0];
  const rest = Array.from({ length: n - 1 }, (_, i) => i + 1);
  for (let i = rest.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [rest[i], rest[j]] = [rest[j], rest[i]]; }
  label.push(...rest);
  const edges = Array.from({ length: n }, () => [-1, -1]);
  for (let j = 1; j < n; j++) {
    let parent;
    if (shape === 0) parent = j - 1;
    else if (shape === 1) parent = 0;
    else if (shape === 2) parent = Math.max(0, j - 1 - Math.floor(rand() * 3));
    else parent = Math.floor(rand() * j);
    const weight = Math.floor(rand() * (2 * limit + 1)) - limit;
    edges[label[j]] = [label[parent], weight];
  }
  return [edges];
}
